/**
 * Lobby Store Service
 * 
 * Centralized state management for the lobby system.
 * Handles all map data, tokens, strokes, images, and walls.
 * Provides optimistic UI updates with server persistence.
 */

import { Injectable, inject, signal, computed } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { LobbyApiService } from './lobby-api.service';
import { LobbySocketService } from './lobby-socket.service';
import { ImageService } from './image.service';
import { TextureService } from './texture.service';
import { MapStorageService } from './map-storage.service';
import { DrawLayerSnapshot, getDefaultDrawLayerId } from '../lobby/draw-layer.utils';
import {
  LobbyData,
  LobbyMap,
  Token,
  Stroke,
  DrawBitmap,
  MapImage,
  LibraryImage,
  LibraryTexture,
  WallHex,
  MeasurementLine,
  HexCoord,
  TextureStroke,
  TextureTile,
  Layer,
  LayerType,
  generateId,
  createEmptyLobby,
  createEmptyMap,
} from '../model/lobby.model';
import { JsonPatch } from '../model/json-patch.model';

@Injectable({ providedIn: 'root' })
export class LobbyStoreService {
  private api = inject(LobbyApiService);
  private socket = inject(LobbySocketService);
  private imageService = inject(ImageService);
  private textureService = inject(TextureService);
  private mapStorage = inject(MapStorageService);

  // Core state
  private lobbySubject = new BehaviorSubject<LobbyData | null>(null);
  lobby$ = this.lobbySubject.asObservable();

  // Global texture library (shared across all lobbies)
  private textureLibrarySignal = signal<LibraryTexture[]>([]);
  // Global image library (shared across all lobbies - like textures)
  private imageLibrarySignal = signal<LibraryImage[]>([]);

  // Current world and map
  worldName = '';
  currentMapId = '';

  // Undo history for draw content (strokes + bitmaps)
  private drawUndoHistory: DrawLayerSnapshot[] = [];
  // Undo history for texture tiles (NEW)
  private textureTileUndoHistory: TextureTile[][] = [];
  private readonly MAX_UNDO = 50;

  // Store hashes of recently sent patches for echo detection (with timestamp)
  private pendingPatchHashes = new Set<string>();

  // Debounced image update system to prevent WebSocket disconnection
  private pendingImageUpdates = new Map<string, Partial<Omit<MapImage, 'id' | 'imageId'>>>();
  private imageUpdateTimeout: any = null;
  private readonly IMAGE_UPDATE_DEBOUNCE_MS = 100; // Debounce image transforms during drag

  // Auto-save to filesystem
  private autoSaveTimeout: any = null;
  private readonly AUTO_SAVE_DELAY = 5000; // 5 seconds after last change

  // ============================================
  // Getters
  // ============================================

  get lobby(): LobbyData | null {
    return this.lobbySubject.value;
  }

  get currentMap(): LobbyMap | null {
    const lobby = this.lobby;
    if (!lobby || !this.currentMapId) return null;
    return lobby.maps[this.currentMapId] || null;
  }

  get tokens(): Token[] {
    return this.currentMap?.tokens || [];
  }

  get drawBitmaps(): DrawBitmap[] {
    return this.currentMap?.drawBitmaps || [];
  }

  get drawLayers(): Layer[] {
    return (this.currentMap?.layers || []).filter(l => l.type === 'draw');
  }

  /** Resolve the active draw layer, creating one if needed */
  getActiveDrawLayerId(): string {
    const map = this.currentMap;
    if (!map) throw new Error('No current map');

    const layers = map.layers || [];
    const active = layers.find(l => l.id === map.activeLayerId);
    if (active?.type === 'draw') return active.id;

    const drawLayer = layers.find(l => l.type === 'draw');
    if (drawLayer) return drawLayer.id;

    return this.addLayer('draw', 'Drawing');
  }

  isActiveDrawLayerLocked(): boolean {
    const map = this.currentMap;
    if (!map?.layers) return false;
    const id = this.getActiveDrawLayerId();
    const layer = map.layers.find(l => l.id === id);
    return layer?.locked ?? false;
  }

  isLayerLocked(layerId: string | undefined): boolean {
    if (!layerId) return false;
    const map = this.currentMap;
    if (!map?.layers) return false;
    const layer = map.layers.find(l => l.id === layerId);
    return layer?.locked ?? false;
  }

  private captureDrawSnapshot(): void {
    this.drawUndoHistory.push({
      strokes: [...this.strokes],
      drawBitmaps: JSON.parse(JSON.stringify(this.drawBitmaps)),
    });
    if (this.drawUndoHistory.length > this.MAX_UNDO) {
      this.drawUndoHistory.shift();
    }
  }

  private applyDrawSnapshot(snapshot: DrawLayerSnapshot): void {
    this.applyPatch({ path: 'strokes', value: snapshot.strokes });
    this.applyPatch({ path: 'drawBitmaps', value: snapshot.drawBitmaps });
  }

  get strokes(): Stroke[] {
    return this.currentMap?.strokes || [];
  }

  get fogStrokes(): Stroke[] {
    return this.currentMap?.fogStrokes || [];
  }

  get textureStrokes(): TextureStroke[] {
    return this.currentMap?.textureStrokes || [];
  }

  get images(): MapImage[] {
    return this.currentMap?.images || [];
  }

  get walls(): WallHex[] {
    return this.currentMap?.walls || [];
  }

  get imageLibrary(): LibraryImage[] {
    return this.imageLibrarySignal();
  }

  imageLibraryReadonly = this.imageLibrarySignal.asReadonly();

  textureLibrary = this.textureLibrarySignal.asReadonly();

  // ============================================
  // Initialization
  // ============================================

  constructor() {
    // Listen for incoming patches from other clients
    this.socket.patches$.subscribe((patch) => {
      // Check if this is an echo of our own patch
      const patchHash = this.hashPatch(patch);
      
      if (this.pendingPatchHashes.has(patchHash)) {
        console.log('[LobbyStore] ⏭️ Skipping echo of our own patch:', patch.path, 'hash:', patchHash.substring(0, 30));
        this.pendingPatchHashes.delete(patchHash);
        return;
      }
      
      this.applyRemotePatch(patch);
    });

    // Listen for main view changes (DM broadcasts map switch)
    this.socket.mainViewChanged$.subscribe(({ mapId }) => {
      console.log('[LobbyStore] 🔄 Main view changed by DM, switching to:', mapId);
      this.handleMainViewChange(mapId);
    });
  }

  /**
   * Create a hash of a complete patch (path + value) for echo detection
   */
  private hashPatch(patch: JsonPatch): string {
    if (Array.isArray(patch.value)) {
      // For arrays, hash path + IDs + length
      const ids = patch.value.map((item: any) => item.id || '').sort().join(',');
      return `${patch.path}:arr:${patch.value.length}:${ids}`;
    }
    return `${patch.path}:${JSON.stringify(patch.value)}`;
  }

  /**
   * Load or create a lobby for a world.
   */
  async loadLobby(worldName: string): Promise<LobbyData> {
    this.worldName = worldName;
    console.log('[LobbyStore] Loading lobby for:', worldName);

    let lobby = await this.api.loadLobby(worldName);

    if (!lobby) {
      console.log('[LobbyStore] Creating new lobby');
      lobby = await this.api.createLobby(worldName);
    }

    // Migrate old data if needed
    lobby = this.migrateLobby(lobby);
    
    this.lobbySubject.next(lobby);

    // Load global texture library
    await this.loadTextureLibrary();
    // Load global image library (NEW: shared across all lobbies)
    await this.loadImageLibrary();

    // Connect socket FIRST before joining rooms
    console.log('[LobbyStore] Connecting to socket...');
    this.socket.connect();
    
    // Wait for socket connection to establish
    let attempts = 0;
    const maxAttempts = 10;
    
    while (attempts < maxAttempts) {
      await new Promise(resolve => setTimeout(resolve, 200));
      if (this.socket.connected) {
        break;
      }
      attempts++;
      console.log(`[LobbyStore] Waiting for socket connection... attempt ${attempts}/${maxAttempts}`);
    }
    
    if (attempts >= maxAttempts) {
      console.warn('[LobbyStore] Socket connection timeout, continuing without real-time sync');
    } else {
      console.log('[LobbyStore] ✅ Socket connected successfully');
    }
    
    // NOW join the lobby room
    await this.socket.joinLobby(worldName);
    console.log('[LobbyStore] ✅ Joined lobby room');

    // Set active map and join its room
    const activeMapId = lobby.activeMapId || Object.keys(lobby.maps)[0] || 'default';
    this.currentMapId = activeMapId;
    lobby.activeMapId = activeMapId;
    
    // Join the map's socket room
    await this.socket.joinMap(worldName, activeMapId);
    console.log('[LobbyStore] ✅ Joined map room:', activeMapId);

    return lobby;
  }

  /**
   * Load the global texture library.
   */
  async loadTextureLibrary(): Promise<void> {
    try {
      const textures = await this.textureService.getTextureLibrary();
      this.textureLibrarySignal.set(textures);
      console.log('[LobbyStore] Loaded global texture library:', textures.length, 'textures');
    } catch (err) {
      console.error('[LobbyStore] Failed to load texture library:', err);
      this.textureLibrarySignal.set([]);
    }
  }

  /**
   * Load the global image library (NEW: same as textures, shared across all lobbies).
   */
  async loadImageLibrary(): Promise<void> {
    try {
      // For now, use localStorage until backend endpoint is created
      const stored = localStorage.getItem('global-image-library');
      if (stored) {
        const images: LibraryImage[] = JSON.parse(stored);
        this.imageLibrarySignal.set(images);
        console.log('[LobbyStore] Loaded global image library:', images.length, 'images');
      } else {
        this.imageLibrarySignal.set([]);
      }
    } catch (err) {
      console.error('[LobbyStore] Failed to load image library:', err);
      this.imageLibrarySignal.set([]);
    }
  }

  /**
   * Save the global image library.
   */
  private saveImageLibrary(): void {
    try {
      localStorage.setItem('global-image-library', JSON.stringify(this.imageLibrarySignal()));
      console.log('[LobbyStore] Saved global image library:', this.imageLibrarySignal().length, 'images');
    } catch (err) {
      console.error('[LobbyStore] Failed to save image library:', err);
    }
  }

  /**
   * Migrate old lobby data to new format.
   */
  private migrateLobby(lobby: LobbyData): LobbyData {
    // Ensure all required fields exist
    if (!lobby.maps) {
      lobby.maps = { default: createEmptyMap('default', 'Main Map') };
    }
    if (!lobby.imageLibrary) {
      lobby.imageLibrary = [];
    }
    if (!lobby.textureLibrary) {
      lobby.textureLibrary = [];
    }
    if (!lobby.activeMapId) {
      lobby.activeMapId = Object.keys(lobby.maps)[0] || 'default';
    }

    // Migrate each map
    for (const mapId of Object.keys(lobby.maps)) {
      const map = lobby.maps[mapId];
      if (!map.tokens) map.tokens = [];
      if (!map.strokes) map.strokes = [];
      if (!map.textureStrokes) map.textureStrokes = [];
      if (!map.walls) map.walls = [];
      if (!map.images) map.images = [];
      if (!map.measurementLines) map.measurementLines = [];
      
      // Filter out broken images with undefined imageId
      map.images = map.images.filter(img => img.imageId);
      
      // Filter out broken library images
      lobby.imageLibrary = lobby.imageLibrary.filter(img => img.imageId);
      
      // LAYER MIGRATION: Create default layers if none exist
      if (!map.layers || map.layers.length === 0) {
        const defaultImageLayer: Layer = {
          id: generateId(),
          name: 'Images',
          type: 'image',
          visible: true,
          locked: false,
          zIndex: 1,
          createdAt: Date.now(),
        };
        const defaultTextureLayer: Layer = {
          id: generateId(),
          name: 'Textures',
          type: 'texture',
          visible: true,
          locked: false,
          zIndex: 0,
          createdAt: Date.now(),
        };
        map.layers = [defaultImageLayer, defaultTextureLayer];
        map.activeLayerId = defaultImageLayer.id;
        
        // Migrate existing images and texture tiles to default layers
        if (map.images && map.images.length > 0) {
          map.images = map.images.map(img => ({
            ...img,
            layerId: img.layerId || defaultImageLayer.id,
          }));
        }
        if (map.textureTiles && map.textureTiles.length > 0) {
          map.textureTiles = map.textureTiles.map(tile => ({
            ...tile,
            layerId: tile.layerId || defaultTextureLayer.id,
          }));
        }
        
        console.log('[LobbyStore] Migrated map', mapId, 'to layer system');
      }

      // DRAW LAYER MIGRATION: ensure at least one draw layer exists
      if (!map.drawBitmaps) map.drawBitmaps = [];
      const hasDrawLayer = (map.layers || []).some(l => l.type === 'draw');
      if (!hasDrawLayer) {
        const maxZ = map.layers && map.layers.length > 0
          ? Math.max(...map.layers.map(l => l.zIndex))
          : 1;
        const defaultDrawLayer: Layer = {
          id: generateId(),
          name: 'Drawing',
          type: 'draw',
          visible: true,
          locked: false,
          zIndex: maxZ + 1,
          createdAt: Date.now(),
        };
        map.layers = [...(map.layers || []), defaultDrawLayer];
        if (map.strokes && map.strokes.length > 0) {
          map.strokes = map.strokes.map(s => ({
            ...s,
            layerId: s.layerId || defaultDrawLayer.id,
          }));
        }
        console.log('[LobbyStore] Migrated map', mapId, 'with default draw layer');
      } else if (map.strokes && map.strokes.length > 0) {
        const defaultId = getDefaultDrawLayerId(map.layers);
        if (defaultId) {
          map.strokes = map.strokes.map(s => ({
            ...s,
            layerId: s.layerId || defaultId,
          }));
        }
      }

      // Assign chronological drawOrder for layered rendering
      let drawOrder = 0;
      if (map.strokes) {
        map.strokes = map.strokes.map(s => ({
          ...s,
          drawOrder: s.drawOrder ?? drawOrder++,
        }));
      }
      if (map.drawBitmaps) {
        map.drawBitmaps = map.drawBitmaps.map(b => ({
          ...b,
          drawOrder: b.drawOrder ?? drawOrder++,
        }));
      }
    }

    return lobby;
  }

  // ============================================
  // Map Operations
  // ============================================

  /**
   * Switch to a different map within the lobby.
   */
  async switchMap(mapId: string): Promise<void> {
    const lobby = this.lobby;
    if (!lobby) return;

    if (!lobby.maps[mapId]) {
      console.error('[LobbyStore] Map not found:', mapId);
      return;
    }

    this.currentMapId = mapId;
    
    // Update lobby's active map
    lobby.activeMapId = mapId;
    lobby.updatedAt = Date.now();
    this.lobbySubject.next({ ...lobby });

    // Join the map's socket room
    await this.socket.joinMap(this.worldName, mapId);
  }

  /**
   * Switch the main view for ALL connected viewers (DM action).
   * This broadcasts the map change to everyone in the lobby.
   */
  async switchMainViewForAll(mapId: string): Promise<void> {
    const lobby = this.lobby;
    if (!lobby) return;

    if (!lobby.maps[mapId]) {
      console.error('[LobbyStore] Map not found:', mapId);
      return;
    }

    // First switch locally
    await this.switchMap(mapId);
    
    // Then broadcast to all other clients
    this.socket.switchMainView(this.worldName, mapId);
  }

  /**
   * Handle incoming main view change from another client (DM).
   */
  private async handleMainViewChange(mapId: string): Promise<void> {
    const lobby = this.lobby;
    if (!lobby) return;

    // Only switch if the map exists and we're not already on it
    if (lobby.maps[mapId] && this.currentMapId !== mapId) {
      await this.switchMap(mapId);
    }
  }

  /**
   * Create a new map within the lobby.
   */
  async createMap(name: string, mapId?: string): Promise<string> {
    const lobby = this.lobby;
    if (!lobby) throw new Error('No lobby loaded');

    const id = mapId || generateId();
    const newMap = createEmptyMap(id, name);
    lobby.maps[newMap.id] = newMap;
    lobby.updatedAt = Date.now();
    
    this.lobbySubject.next({ ...lobby });
    await this.api.saveLobby(this.worldName, lobby);

    return newMap.id;
  }

  /**
   * Delete a map from the lobby.
   */
  async deleteMap(mapId: string): Promise<void> {
    const lobby = this.lobby;
    if (!lobby) return;

    const mapCount = Object.keys(lobby.maps).length;
    if (mapCount <= 1) {
      console.warn('[LobbyStore] Cannot delete the only map');
      return;
    }

    delete lobby.maps[mapId];

    // Switch to another map if we deleted the active one
    if (lobby.activeMapId === mapId) {
      const newActiveId = Object.keys(lobby.maps)[0];
      await this.switchMap(newActiveId);
    }

    lobby.updatedAt = Date.now();
    this.lobbySubject.next({ ...lobby });
    await this.api.saveLobby(this.worldName, lobby);
  }

  /**
   * Rename a map.
   */
  async renameMap(mapId: string, name: string): Promise<void> {
    const lobby = this.lobby;
    if (!lobby || !lobby.maps[mapId]) return;

    lobby.maps[mapId].name = name;
    lobby.maps[mapId].updatedAt = Date.now();
    lobby.updatedAt = Date.now();

    this.lobbySubject.next({ ...lobby });
    await this.api.saveLobby(this.worldName, lobby);
  }

  /**
   * Update map background color.
   */
  async updateMapBackground(mapId: string, color: string): Promise<void> {
    const lobby = this.lobby;
    if (!lobby || !lobby.maps[mapId]) return;

    lobby.maps[mapId].backgroundColor = color;
    lobby.maps[mapId].updatedAt = Date.now();
    lobby.updatedAt = Date.now();

    this.lobbySubject.next({ ...lobby });
    await this.api.saveLobby(this.worldName, lobby);
  }

  /**
   * Alias for switchMap for consistency.
   */
  async setActiveMap(mapId: string): Promise<void> {
    await this.switchMap(mapId);
  }

  // ============================================
  // Token Operations
  // ============================================

  /**
   * Add a token to the current map.
   */
  addToken(token: Omit<Token, 'id'>): void {
    const newToken: Token = {
      ...token,
      id: generateId(),
    };

    const tokens = [...this.tokens, newToken];
    this.applyPatch({ path: 'tokens', value: tokens });
  }

  /**
   * Move a token to a new hex position.
   */
  moveToken(tokenId: string, position: HexCoord): void {
    const tokens = [...this.tokens];
    const index = tokens.findIndex(t => t.id === tokenId);
    if (index === -1) return;

    const oldPositions = new Map<string, HexCoord>(
      tokens.map(t => [t.id, { q: t.position.q, r: t.position.r }])
    );

    tokens[index] = { ...tokens[index], position };

    // If a distance-linked token is moved directly, treat the new placement as the new constraint.
    const movedToken = tokens[index];
    if (movedToken.parentTokenId && movedToken.linkedTokenType === 'keepOffset') {
      const parent = tokens.find(t => t.id === movedToken.parentTokenId);
      if (parent) {
        tokens[index] = {
          ...movedToken,
          linkedOffset: {
            q: position.q - parent.position.q,
            r: position.r - parent.position.r,
          },
        };
      }
    }

    if (movedToken.parentTokenId && movedToken.linkedTokenType === 'keepDistance') {
      const parent = tokens.find(t => t.id === movedToken.parentTokenId);
      if (parent) {
        tokens[index] = {
          ...movedToken,
          linkedDistance: this.axialDistance(parent.position, position),
        };
      }
    }

    const moveLinkedDescendants = (parentId: string): void => {
      const parent = tokens.find(t => t.id === parentId);
      if (!parent) return;
      const oldParentPosition = oldPositions.get(parentId) ?? parent.position;

      for (let i = 0; i < tokens.length; i++) {
        const child = tokens[i];
        if (child.parentTokenId !== parentId || child.linkedTokenType === 'free') {
          continue;
        }

        const oldChildPosition = oldPositions.get(child.id) ?? child.position;

        if (child.linkedTokenType === 'keepOffset') {
          const offset = child.linkedOffset ?? {
            q: oldChildPosition.q - oldParentPosition.q,
            r: oldChildPosition.r - oldParentPosition.r,
          };
          tokens[i] = {
            ...child,
            linkedOffset: offset,
            position: { q: parent.position.q + offset.q, r: parent.position.r + offset.r },
          };
          moveLinkedDescendants(child.id);
          continue;
        }

        if (child.linkedTokenType === 'keepDistance') {
          const desiredDistance = child.linkedDistance ?? this.axialDistance(oldParentPosition, oldChildPosition);
          const currentDistance = this.axialDistance(parent.position, oldChildPosition);

          if (currentDistance === desiredDistance) {
            tokens[i] = {
              ...child,
              linkedDistance: desiredDistance,
              position: oldChildPosition,
            };
            moveLinkedDescendants(child.id);
            continue;
          }

          const constrained = this.closestHexAtDistance(
            parent.position,
            oldChildPosition,
            desiredDistance,
            oldParentPosition
          );
          tokens[i] = {
            ...child,
            linkedDistance: desiredDistance,
            position: constrained,
          };
          moveLinkedDescendants(child.id);
        }
      }
    };

    moveLinkedDescendants(tokenId);

    this.applyPatch({ path: 'tokens', value: tokens });
  }

  /**
   * Rotate a token and propagate rotation to keepOffset children.
   */
  rotateToken(tokenId: string, deltaDegrees: number): void {
    const tokens = [...this.tokens];
    const index = tokens.findIndex(t => t.id === tokenId);
    if (index === -1) return;

    const oldRotation = tokens[index].rotation ?? 0;
    const newRotation = ((oldRotation + deltaDegrees) % 360 + 360) % 360;
    tokens[index] = { ...tokens[index], rotation: newRotation };

    const parent = tokens[index];
    for (let i = 0; i < tokens.length; i++) {
      const child = tokens[i];
      if (child.parentTokenId !== tokenId) continue;

      if (child.linkedTokenType === 'keepOffset' && child.linkedOffset) {
        const rotatedOffset = this.rotateHexOffset(child.linkedOffset, deltaDegrees);
        tokens[i] = {
          ...child,
          linkedOffset: rotatedOffset,
          rotation: ((child.rotation ?? 0) + deltaDegrees + 360) % 360,
          position: {
            q: parent.position.q + rotatedOffset.q,
            r: parent.position.r + rotatedOffset.r,
          },
        };
      }
    }

    this.applyPatch({ path: 'tokens', value: tokens });
  }

  private rotateHexOffset(offset: { q: number; r: number }, degrees: number): { q: number; r: number } {
    let q = offset.q;
    let r = offset.r;

    const normalized = ((Math.round(degrees / 60) % 6) + 6) % 6;
    for (let step = 0; step < normalized; step++) {
      const nextQ = -r;
      const nextR = q + r;
      q = nextQ;
      r = nextR;
    }

    return { q, r };
  }

  private axialDistance(a: HexCoord, b: HexCoord): number {
    const dq = b.q - a.q;
    const dr = b.r - a.r;
    return (Math.abs(dq) + Math.abs(dr) + Math.abs(dq + dr)) / 2;
  }

  private closestHexAtDistance(
    center: HexCoord,
    from: HexCoord,
    distance: number,
    oldCenter?: HexCoord
  ): HexCoord {
    if (distance <= 0) return { ...center };

    let best = { q: center.q + distance, r: center.r };
    let bestFromDist = this.axialDistance(from, best);
    let bestOldCenterDist = oldCenter ? this.axialDistance(best, oldCenter) : Number.MAX_SAFE_INTEGER;

    for (let dq = -distance; dq <= distance; dq++) {
      for (let dr = -distance; dr <= distance; dr++) {
        const candidate = { q: center.q + dq, r: center.r + dr };
        if (this.axialDistance(center, candidate) !== distance) continue;
        const fromDist = this.axialDistance(from, candidate);
        const oldCenterDist = oldCenter ? this.axialDistance(candidate, oldCenter) : Number.MAX_SAFE_INTEGER;

        if (
          fromDist < bestFromDist ||
          (fromDist === bestFromDist && oldCenterDist < bestOldCenterDist)
        ) {
          best = candidate;
          bestFromDist = fromDist;
          bestOldCenterDist = oldCenterDist;
        }
      }
    }

    return best;
  }

  /**
   * Update a token's properties.
   */
  updateToken(tokenId: string, updates: Partial<Omit<Token, 'id'>>): void {
    const tokens = [...this.tokens];
    const index = tokens.findIndex(t => t.id === tokenId);
    if (index === -1) return;

    tokens[index] = { ...tokens[index], ...updates };
    this.applyPatch({ path: 'tokens', value: tokens });
  }

  /**
   * Remove a token from the map.
   */
  removeToken(tokenId: string): void {
    const tokens = this.tokens.filter(t => t.id !== tokenId);
    this.applyPatch({ path: 'tokens', value: tokens });
  }

  // ============================================
  // Stroke Operations (Drawing)
  // ============================================

  /**
   * Next chronological draw order for strokes/bitmaps on the current map.
   */
  getNextDrawOrder(): number {
    let max = 0;
    for (const s of this.strokes) {
      max = Math.max(max, s.drawOrder ?? 0);
    }
    for (const b of this.drawBitmaps) {
      max = Math.max(max, b.drawOrder ?? 0);
    }
    return max + 1;
  }

  /**
   * Add a drawing stroke.
   */
  addStroke(stroke: Omit<Stroke, 'id'>): void {
    this.captureDrawSnapshot();

    const layerId = stroke.layerId || this.getActiveDrawLayerId();
    const newStroke: Stroke = {
      ...stroke,
      layerId,
      drawOrder: stroke.drawOrder ?? this.getNextDrawOrder(),
      id: generateId(),
    };

    const strokes = [...this.strokes, newStroke];
    this.applyPatch({ path: 'strokes', value: strokes });
  }

  addDrawBitmap(bitmap: Omit<DrawBitmap, 'id'>): void {
    this.captureDrawSnapshot();
    const newBitmap: DrawBitmap = {
      ...bitmap,
      drawOrder: bitmap.drawOrder ?? this.getNextDrawOrder(),
      id: generateId(),
    };
    const drawBitmaps = [...this.drawBitmaps, newBitmap];
    this.applyPatch({ path: 'drawBitmaps', value: drawBitmaps });
  }

  /** Apply multiple draw changes in one undo step (single UI notification) */
  applyDrawChanges(strokes: Stroke[], drawBitmaps: DrawBitmap[]): void {
    this.captureDrawSnapshot();
    const map = this.currentMap;
    if (!map) return;

    const patches: JsonPatch[] = [
      { path: 'strokes', value: strokes },
      { path: 'drawBitmaps', value: drawBitmaps },
    ];

    for (const patch of patches) {
      const patchHash = this.hashPatch(patch);
      this.pendingPatchHashes.add(patchHash);
      setTimeout(() => this.pendingPatchHashes.delete(patchHash), 10000);
      this.applyJsonPatch(map, patch);
    }
    map.updatedAt = Date.now();

    const lobby = this.lobby;
    if (lobby) {
      lobby.maps[this.currentMapId] = { ...map };
      lobby.updatedAt = Date.now();
      this.lobbySubject.next({ ...lobby });

      this.api.saveLobby(this.worldName, lobby).catch(err => {
        console.error('[LobbyStore] Failed to save:', err);
      });
      this.scheduleAutoSave();
    }

    this.socket.ensureConnected().then(() => {
      for (const patch of patches) {
        this.socket.sendPatch(this.worldName, this.currentMapId, patch);
      }
    }).catch(err => {
      console.error('[LobbyStore] ❌ Socket not ready, draw patches not broadcast:', err);
    });
  }

  /**
   * Add a texture stroke.
   */
  addTextureStroke(textureStroke: Omit<TextureStroke, 'id'>): void {
    const newTextureStroke: TextureStroke = {
      ...textureStroke,
      id: generateId(),
    };

    const textureStrokes = [...this.textureStrokes, newTextureStroke];
    this.applyPatch({ path: 'textureStrokes', value: textureStrokes });
  }

  /**
   * Clear all texture strokes and tiles.
   */
  clearAllTextures(): void {
    this.applyPatch({ path: 'textureStrokes', value: [] });
    this.applyPatch({ path: 'textureTiles', value: [] });
  }

  /**
   * Update texture tiles (tile-based texture system).
   */
  updateMapTiles(tiles: TextureTile[]): void {
    this.applyPatch({ path: 'textureTiles', value: tiles });
  }

  /**
   * Remove a specific stroke by ID (for eraser).
   */
  removeStroke(strokeId: string): void {
    const strokes = this.strokes.filter(s => s.id !== strokeId);
    this.applyPatch({ path: 'strokes', value: strokes });
  }

  /**
   * Undo the last stroke.
   */
  undoStroke(): boolean {
    if (this.drawUndoHistory.length === 0) return false;
    const previous = this.drawUndoHistory.pop()!;
    this.applyDrawSnapshot(previous);
    return true;
  }

  /**
   * Capture current texture tiles for undo (NEW).
   * Call this BEFORE starting a texture stroke.
   */
  captureTextureTileSnapshot(): void {
    const currentTiles = this.currentMap?.textureTiles || [];
    // Deep copy the tiles array
    const snapshot = JSON.parse(JSON.stringify(currentTiles));
    this.textureTileUndoHistory.push(snapshot);
    
    // Limit history size
    if (this.textureTileUndoHistory.length > this.MAX_UNDO) {
      this.textureTileUndoHistory.shift();
    }
  }

  /**
   * Undo the last texture tile changes (NEW).
   */
  undoTextureTiles(): boolean {
    if (this.textureTileUndoHistory.length === 0) return false;

    const previousTiles = this.textureTileUndoHistory.pop()!;
    // Apply without adding to undo history (direct patch)
    this.applyPatch({ path: 'textureTiles', value: previousTiles });
    return true;
  }

  /**
   * Delete an image from the current map.
   */
  deleteImage(imageId: string): void {
    const images = this.images.filter(img => img.id !== imageId);
    this.applyPatch({ path: 'images', value: images });
  }

  /**
   * Clear all strokes.
   */
  clearStrokes(layerId?: string): void {
    const targetId = layerId || this.getActiveDrawLayerId();
    const hasStrokes = this.strokes.some(s => (s.layerId || targetId) === targetId);
    const hasBitmaps = this.drawBitmaps.some(b => b.layerId === targetId);
    if (!hasStrokes && !hasBitmaps) return;

    this.captureDrawSnapshot();

    const strokes = this.strokes.filter(s => (s.layerId || targetId) !== targetId);
    const drawBitmaps = this.drawBitmaps.filter(b => b.layerId !== targetId);
    this.applyPatch({ path: 'strokes', value: strokes });
    this.applyPatch({ path: 'drawBitmaps', value: drawBitmaps });
  }

  /**
   * Add a fog of war stroke.
   */
  addFogStroke(stroke: Omit<Stroke, 'id'>): void {
    const newStroke: Stroke = { ...stroke, id: generateId() };
    const fogStrokes = [...this.fogStrokes, newStroke];
    this.applyPatch({ path: 'fogStrokes', value: fogStrokes });
  }

  /**
   * Clear all fog of war strokes.
   */
  clearFog(): void {
    if (this.fogStrokes.length === 0) return;
    this.applyPatch({ path: 'fogStrokes', value: [] });
  }

  // ============================================
  // Image Operations (Map Background)
  // ============================================

  /**
   * Add an image to the map.
   * @param imageId - The image ID from ImageService (not base64!)
   * @returns The generated MapImage ID
   */
  addImage(imageId: string, x: number, y: number, width: number, height: number): string {
    const map = this.currentMap;
    if (!map) throw new Error('No current map');

    // Use active layer, or find first image layer, or create one
    let targetLayerId = map.activeLayerId;
    
    if (!targetLayerId || !map.layers || map.layers.length === 0) {
      // Create default layers if none exist
      const imageLayerId = this.addLayer('image', 'Images');
      targetLayerId = imageLayerId;
    } else {
      // Verify active layer is an image layer
      const activeLayer = map.layers.find(l => l.id === targetLayerId);
      if (!activeLayer || activeLayer.type !== 'image') {
        // Find first image layer
        const imageLayer = map.layers.find(l => l.type === 'image');
        if (imageLayer) {
          targetLayerId = imageLayer.id;
        } else {
          // Create image layer
          targetLayerId = this.addLayer('image', 'Images');
        }
      }
    }

    const newImage: MapImage = {
      id: generateId(),
      imageId,
      x,
      y,
      width,
      height,
      rotation: 0,
      zIndex: Math.max(0, ...this.images.map(i => i.zIndex)) + 1,
      layer: 'foreground', // Legacy property (DEPRECATED)
      layerId: targetLayerId,
    };

    const images = [...this.images, newImage];
    this.applyPatch({ path: 'images', value: images });
    return newImage.id;
  }

  /**
   * Update an image's transform properties with debouncing.
   * Prevents WebSocket disconnection during rapid updates (dragging/transforming).
   */
  updateImage(id: string, updates: Partial<Omit<MapImage, 'id' | 'imageId'>>): void {
    // Update local state immediately for responsive UI
    const images = [...this.images];
    const index = images.findIndex(i => i.id === id);
    if (index === -1) return;

    images[index] = { ...images[index], ...updates };
    this.updateLocalImages(images);

    // Queue the update for debounced sending
    const currentPending = this.pendingImageUpdates.get(id) || {};
    this.pendingImageUpdates.set(id, { ...currentPending, ...updates });
    this.scheduleImageUpdate();
  }

  /**
   * Schedule a debounced image update to prevent overwhelming WebSocket.
   */
  private scheduleImageUpdate(): void {
    if (this.imageUpdateTimeout) {
      clearTimeout(this.imageUpdateTimeout);
    }

    this.imageUpdateTimeout = setTimeout(() => {
      this.flushPendingImageUpdates();
      this.imageUpdateTimeout = null;
    }, this.IMAGE_UPDATE_DEBOUNCE_MS);
  }

  /**
   * Flush all pending image updates to WebSocket.
   */
  private flushPendingImageUpdates(): void {
    if (this.pendingImageUpdates.size === 0) return;

    const images = [...this.images];
    let hasChanges = false;

    for (const [id, updates] of this.pendingImageUpdates.entries()) {
      const index = images.findIndex(i => i.id === id);
      if (index !== -1) {
        images[index] = { ...images[index], ...updates };
        hasChanges = true;
      }
    }

    if (hasChanges) {
      this.applyPatch({ path: 'images', value: images });
    }

    this.pendingImageUpdates.clear();
  }

  /**
   * Update local images state without sending to server.
   * Used for optimistic UI updates during debounce period.
   */
  private updateLocalImages(images: MapImage[]): void {
    const lobby = this.lobby;
    if (!lobby || !this.currentMapId) return;

    const map = lobby.maps[this.currentMapId];
    if (!map) return;

    const updatedMap: LobbyMap = { ...map, images };
    const updatedLobby: LobbyData = {
      ...lobby,
      maps: { ...lobby.maps, [this.currentMapId]: updatedMap },
    };

    this.lobbySubject.next(updatedLobby);
  }

  /**
   * Remove an image from the map.
   */
  removeImage(id: string): void {
    const images = this.images.filter(i => i.id !== id);
    this.applyPatch({ path: 'images', value: images });
  }

  // Z-index management
  moveImageForward(id: string): void {
    const images = [...this.images];
    const current = images.find(i => i.id === id);
    if (!current) return;

    const higherImages = images.filter(i => i.zIndex > current.zIndex);
    if (higherImages.length === 0) return;

    const nextZ = Math.min(...higherImages.map(i => i.zIndex));
    current.zIndex = nextZ + 0.5;

    this.normalizeZIndices(images);
    this.applyPatch({ path: 'images', value: images });
  }

  moveImageBackward(id: string): void {
    const images = [...this.images];
    const current = images.find(i => i.id === id);
    if (!current) return;

    const lowerImages = images.filter(i => i.zIndex < current.zIndex);
    if (lowerImages.length === 0) return;

    const prevZ = Math.max(...lowerImages.map(i => i.zIndex));
    current.zIndex = prevZ - 0.5;

    this.normalizeZIndices(images);
    this.applyPatch({ path: 'images', value: images });
  }

  moveImageToFront(id: string): void {
    const images = [...this.images];
    const index = images.findIndex(i => i.id === id);
    if (index === -1) return;

    const targetImage = images[index];
    const targetLayer = targetImage.layer || 'background';

    // Find max zIndex within the same layer
    const maxZ = Math.max(0, ...images
      .filter(i => (i.layer || 'background') === targetLayer)
      .map(i => i.zIndex));
    
    images[index] = { ...images[index], zIndex: maxZ + 1 };
    this.applyPatch({ path: 'images', value: images });
  }

  moveImageToBack(id: string): void {
    const images = [...this.images];
    const index = images.findIndex(i => i.id === id);
    if (index === -1) return;

    const targetImage = images[index];
    const targetLayer = targetImage.layer || 'background';

    // Find min zIndex within the same layer
    const minZ = Math.min(0, ...images
      .filter(i => (i.layer || 'background') === targetLayer)
      .map(i => i.zIndex));
    
    images[index] = { ...images[index], zIndex: minZ - 1 };
    this.applyPatch({ path: 'images', value: images });
  }

  toggleImageLayer(id: string): void {
    const images = [...this.images];
    const index = images.findIndex(i => i.id === id);
    if (index === -1) return;

    const currentLayer = images[index].layer || 'background';
    const newLayer = currentLayer === 'foreground' ? 'background' : 'foreground';
    
    images[index] = { ...images[index], layer: newLayer };
    this.applyPatch({ path: 'images', value: images });
  }

  private normalizeZIndices(images: MapImage[]): void {
    const sorted = [...images].sort((a, b) => a.zIndex - b.zIndex);
    sorted.forEach((img, idx) => {
      const original = images.find(i => i.id === img.id);
      if (original) original.zIndex = idx;
    });
  }

  // ============================================
  // Layer Management
  // ============================================

  /**
   * Get layers for current map.
   * Layers are created during migration in migrateLobby().
   */
  get layers(): Layer[] {
    const map = this.currentMap;
    if (!map) {
      console.log('[LobbyStore] layers getter: no current map');
      return [];
    }
    const layers = map.layers || [];
    console.log('[LobbyStore] layers getter: returning', layers.length, 'layers for map', map.id, ':', layers.map(l => l.name));
    return layers;
  }

  /**
   * Get active layer ID for current map.
   */
  get activeLayerId(): string | null {
    return this.currentMap?.activeLayerId || null;
  }

  /**
   * Add a new layer to the current map.
   */
  addLayer(type: LayerType, name?: string): string {
    const map = this.currentMap;
    if (!map) throw new Error('No current map');

    // Initialize layers if needed
    if (!map.layers) {
      map.layers = [];
      map.activeLayerId = undefined;
    }

    const maxZIndex = map.layers.length > 0 
      ? Math.max(...map.layers.map(l => l.zIndex)) 
      : -1;

    const newLayer: Layer = {
      id: generateId(),
      name: name || (type === 'image' ? 'Images' : type === 'texture' ? 'Textures' : 'Drawing') + ` ${map.layers.length + 1}`,
      type,
      visible: true,
      locked: false,
      zIndex: maxZIndex + 1,
      createdAt: Date.now(),
    };

    const layers = [...map.layers, newLayer];
    this.applyPatch({ path: 'layers', value: layers });

    // Draw layers become active when created
    if (type === 'draw' || !map.activeLayerId) {
      this.applyPatch({ path: 'activeLayerId', value: newLayer.id });
    }

    return newLayer.id;
  }

  /**
   * Delete a layer and all its content.
   */
  deleteLayer(layerId: string): void {
    const map = this.currentMap;
    if (!map || !map.layers) return;

    const layers = map.layers.filter(l => l.id !== layerId);
    const deletedLayer = map.layers.find(l => l.id === layerId);
    if (!deletedLayer) return;

    // Draw layers: require at least one remaining
    if (deletedLayer.type === 'draw') {
      const remainingDraw = layers.filter(l => l.type === 'draw');
      if (remainingDraw.length === 0) {
        console.warn('[LobbyStore] Cannot delete the only draw layer');
        return;
      }
    } else if (layers.length === 0) {
      console.warn('[LobbyStore] Cannot delete the only layer');
      return;
    }

    this.applyPatch({ path: 'layers', value: layers });

    // Remove all images and tiles on this layer
    const images = this.images.filter(img => img.layerId !== layerId);
    if (images.length !== this.images.length) {
      this.applyPatch({ path: 'images', value: images });
    }

    const tiles = (map.textureTiles || []).filter(tile => tile.layerId !== layerId);
    if (tiles.length !== (map.textureTiles || []).length) {
      this.applyPatch({ path: 'textureTiles', value: tiles });
    }

    // Remove draw content on this layer
    if (deletedLayer.type === 'draw') {
      const strokes = this.strokes.filter(s => s.layerId !== layerId);
      const drawBitmaps = this.drawBitmaps.filter(b => b.layerId !== layerId);
      if (strokes.length !== this.strokes.length) {
        this.applyPatch({ path: 'strokes', value: strokes });
      }
      if (drawBitmaps.length !== this.drawBitmaps.length) {
        this.applyPatch({ path: 'drawBitmaps', value: drawBitmaps });
      }
    }

    // Switch active layer if needed
    if (map.activeLayerId === layerId) {
      this.applyPatch({ path: 'activeLayerId', value: layers[0]?.id || null });
    }
  }

  /**
   * Rename a layer.
   */
  renameLayer(layerId: string, name: string): void {
    const map = this.currentMap;
    if (!map || !map.layers) return;

    const layers = [...map.layers];
    const index = layers.findIndex(l => l.id === layerId);
    if (index === -1) return;

    layers[index] = { ...layers[index], name };
    this.applyPatch({ path: 'layers', value: layers });
  }

  /**
   * Toggle layer visibility.
   */
  toggleLayerVisibility(layerId: string): void {
    const map = this.currentMap;
    if (!map || !map.layers) return;

    const layers = [...map.layers];
    const index = layers.findIndex(l => l.id === layerId);
    if (index === -1) return;

    layers[index] = { ...layers[index], visible: !layers[index].visible };
    this.applyPatch({ path: 'layers', value: layers });
  }

  /**
   * Toggle layer lock state.
   */
  toggleLayerLock(layerId: string): void {
    const map = this.currentMap;
    if (!map || !map.layers) return;

    const layers = [...map.layers];
    const index = layers.findIndex(l => l.id === layerId);
    if (index === -1) return;

    layers[index] = { ...layers[index], locked: !layers[index].locked };
    this.applyPatch({ path: 'layers', value: layers });
  }

  /**
   * Set the active layer for new content.
   */
  setActiveLayer(layerId: string): void {
    this.applyPatch({ path: 'activeLayerId', value: layerId });
  }

  /**
   * Reorder layers (update all zIndex values).
   */
  reorderLayers(reorderedLayers: Layer[]): void {
    this.applyPatch({ path: 'layers', value: reorderedLayers });
  }

  // ============================================
  // Image Library Operations
  // ============================================

  /**
   * Add an image to the GLOBAL reusable library (NEW: shared across all lobbies).
   * Uploads the image to the server first.
   */
  async addLibraryImage(source: string | File, name: string): Promise<LibraryImage> {
    const imageId = typeof source === 'string'
      ? await this.imageService.uploadImage(source)
      : await this.imageService.uploadImageFile(source, source.name);
    
    const newImage: LibraryImage = {
      id: generateId(),
      name,
      imageId,
      width: 200,
      height: 200,
      createdAt: Date.now(),
    };

    // Add to GLOBAL library (signal)
    const current = this.imageLibrarySignal();
    this.imageLibrarySignal.set([...current, newImage]);
    this.saveImageLibrary(); // Persist to localStorage

    console.log('[LobbyStore] Added image to GLOBAL library:', name);
    return newImage;
  }

  /**
   * Update a library image's name (NEW: updates GLOBAL library).
   */
  async updateLibraryImage(id: string, name: string): Promise<void> {
    const current = this.imageLibrarySignal();
    const index = current.findIndex(i => i.id === id);
    if (index === -1) return;

    const updated = [...current];
    updated[index] = { ...updated[index], name };
    this.imageLibrarySignal.set(updated);
    this.saveImageLibrary(); // Persist to localStorage
    console.log('[LobbyStore] Updated image in GLOBAL library:', name);
  }

  /**
   * Remove an image from the library (NEW: removes from GLOBAL library).
   */
  async removeLibraryImage(id: string): Promise<void> {
    const current = this.imageLibrarySignal();
    this.imageLibrarySignal.set(current.filter(i => i.id !== id));
    this.saveImageLibrary(); // Persist to localStorage
    console.log('[LobbyStore] Removed image from GLOBAL library');
  }

  /**
   * Add a texture to the global texture library.
   * Uploads the texture to the server first.
   */
  async addLibraryTexture(base64Data: string, name: string, tileSize: number = 100): Promise<LibraryTexture> {
    // Upload to global library (uploads file and adds metadata)
    const newTexture = await this.textureService.addToTextureLibrary(base64Data, name, tileSize);
    
    // Update local state
    const currentLibrary = this.textureLibrarySignal();
    this.textureLibrarySignal.set([...currentLibrary, newTexture]);

    return newTexture;
  }

  // ============================================
  // Wall Operations
  // ============================================

  /**
   * Add a wall at a hex position.
   */
  addWall(hex: HexCoord): void {
    const exists = this.walls.some(w => w.q === hex.q && w.r === hex.r);
    if (exists) return;

    const walls = [...this.walls, { q: hex.q, r: hex.r }];
    this.applyPatch({ path: 'walls', value: walls });
  }

  /**
   * Remove a wall from a hex position.
   */
  removeWall(hex: HexCoord): void {
    const walls = this.walls.filter(w => !(w.q === hex.q && w.r === hex.r));
    this.applyPatch({ path: 'walls', value: walls });
  }

  /**
   * Toggle a wall at a hex position.
   */
  toggleWall(hex: HexCoord): void {
    const exists = this.walls.some(w => w.q === hex.q && w.r === hex.r);
    if (exists) {
      this.removeWall(hex);
    } else {
      this.addWall(hex);
    }
  }

  /**
   * Clear all walls.
   */
  clearWalls(): void {
    this.applyPatch({ path: 'walls', value: [] });
  }

  /**
   * Apply a batch of wall changes at once (add/remove multiple walls in one save).
   * This prevents flickering and server overload from per-hex saves.
   */
  applyWallBatch(changes: { hex: HexCoord; action: 'add' | 'remove' }[]): void {
    let walls = [...this.walls];
    
    for (const change of changes) {
      if (change.action === 'add') {
        const exists = walls.some(w => w.q === change.hex.q && w.r === change.hex.r);
        if (!exists) {
          walls.push({ q: change.hex.q, r: change.hex.r });
        }
      } else {
        walls = walls.filter(w => !(w.q === change.hex.q && w.r === change.hex.r));
      }
    }
    
    this.applyPatch({ path: 'walls', value: walls });
  }

  /**
   * Clean up orphaned images on the server and refresh the lobby.
   */
  async cleanupOrphanedImages(): Promise<void> {
    try {
      console.log('[LobbyStore] Starting image cleanup...');
      const response = await fetch('http://localhost:3000/api/images/cleanup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      
      if (response.ok) {
        const result = await response.json();
        console.log('[LobbyStore] Cleanup result:', result);
        
        // Refresh the lobby after cleanup
        if (this.worldName) {
          await this.loadLobby(this.worldName);
        }
      } else {
        console.error('[LobbyStore] Cleanup failed:', response.statusText);
      }
    } catch (error) {
      console.error('[LobbyStore] Error during cleanup:', error);
    }
  }

  // ============================================
  // Patch System
  // ============================================

  /**
   * Apply a patch locally and send to server.
   * Ensures socket is connected before broadcasting.
   */
  private applyPatch(patch: JsonPatch): void {
    const map = this.currentMap;
    if (!map) {
      console.warn('[LobbyStore] ⚠️ Cannot apply patch - no current map');
      return;
    }

    // Track pending patch hash for echo filtering (store multiple hashes for rapid operations)
    const patchHash = this.hashPatch(patch);
    this.pendingPatchHashes.add(patchHash);
    
    // Auto-cleanup after 10 seconds to prevent memory leak
    setTimeout(() => this.pendingPatchHashes.delete(patchHash), 10000);
    
    console.log('[LobbyStore] 📤 Applying patch locally and broadcasting:', patch.path, 'hash:', patchHash.substring(0, 30));

    // Apply locally
    this.applyJsonPatch(map, patch);
    map.updatedAt = Date.now();

    // Update lobby
    const lobby = this.lobby;
    if (lobby) {
      lobby.maps[this.currentMapId] = { ...map };
      lobby.updatedAt = Date.now();
      this.lobbySubject.next({ ...lobby });

      // Save to server
      this.api.saveLobby(this.worldName, lobby).catch(err => {
        console.error('[LobbyStore] Failed to save:', err);
      });
      
      // Schedule filesystem auto-save (debounced)
      this.scheduleAutoSave();
    }

    // Ensure socket is connected before broadcasting (async, don't block)
    this.socket.ensureConnected().then(() => {
      console.log('[LobbyStore] ✅ Socket ready, sending patch:', patch.path, 'to map:', this.currentMapId);
      this.socket.sendPatch(this.worldName, this.currentMapId, patch);
    }).catch(err => {
      console.error('[LobbyStore] ❌ Socket not ready, patch not broadcast:', patch.path);
    });
  }

  /**
   * Apply a patch received from another client.
   */
  private applyRemotePatch(patch: JsonPatch): void {
    const map = this.currentMap;
    if (!map) {
      console.warn('[LobbyStore] ⚠️ Cannot apply remote patch - no current map');
      return;
    }

    console.log('[LobbyStore] 📥 Applying remote patch:', patch.path, Array.isArray(patch.value) ? `array[${patch.value.length}]` : typeof patch.value);
    
    // Trust the remote patch as source of truth (last write wins)
    // Echo detection ensures we don't overwrite our own changes
    this.applyJsonPatch(map, patch);
    map.updatedAt = Date.now();

    const lobby = this.lobby;
    if (lobby) {
      lobby.maps[this.currentMapId] = { ...map };
      this.lobbySubject.next({ ...lobby });
    }
  }

  /**
   * Apply a JSON patch to a target object.
   */
  private applyJsonPatch(target: any, patch: JsonPatch): void {
    // Normalize path: remove leading slash, replace slashes with dots
    let normalizedPath = patch.path.trim();
    if (normalizedPath.startsWith('/')) {
      normalizedPath = normalizedPath.substring(1);
    }
    normalizedPath = normalizedPath.replace(/\//g, '.');
    
    const keys = normalizedPath.split('.');
    
    if (keys.length === 1) {
      target[keys[0]] = patch.value;
      return;
    }

    let current = target;
    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      const index = parseInt(key, 10);

      if (!isNaN(index) && Array.isArray(current)) {
        current = current[index];
      } else {
        current = current[key] ??= {};
      }
    }

    const finalKey = keys[keys.length - 1];
    
    // Handle array append operation: '-' means append to array
    if (finalKey === '-' && Array.isArray(current)) {
      current.push(patch.value);
      return;
    }
    
    const finalIndex = parseInt(finalKey, 10);

    if (!isNaN(finalIndex) && Array.isArray(current)) {
      current[finalIndex] = patch.value;
    } else {
      current[finalKey] = patch.value;
    }
  }

  // ============================================
  // Filesystem Auto-Save (NEW)
  // ============================================

  /**
   * Schedule an auto-save of the current map to filesystem.
   * Debounced to avoid overwhelming the filesystem with writes.
   */
  private scheduleAutoSave(): void {
    if (this.autoSaveTimeout) {
      clearTimeout(this.autoSaveTimeout);
    }

    this.autoSaveTimeout = setTimeout(() => {
      this.performAutoSave();
      this.autoSaveTimeout = null;
    }, this.AUTO_SAVE_DELAY);
  }

  /**
   * Perform the actual filesystem save.
   */
  private async performAutoSave(): Promise<void> {
    const map = this.currentMap;
    if (!map || !this.worldName) {
      return;
    }

    try {
      const success = await this.mapStorage.saveMap(this.worldName, map.name, map);
      if (success) {
        console.log('[LobbyStore] 💾 Map auto-saved to filesystem:', this.worldName, '/', map.name);
      } else {
        console.warn('[LobbyStore] ⚠️ Auto-save failed');
      }
    } catch (error) {
      console.error('[LobbyStore] ❌ Auto-save error:', error);
    }
  }

  /**
   * Manually save the current map to filesystem (for user-triggered saves).
   */
  async manualSave(): Promise<boolean> {
    const map = this.currentMap;
    if (!map || !this.worldName) {
      return false;
    }

    // Cancel any pending auto-save
    if (this.autoSaveTimeout) {
      clearTimeout(this.autoSaveTimeout);
      this.autoSaveTimeout = null;
    }

    return await this.mapStorage.saveMap(this.worldName, map.name, map);
  }

  /**
   * Create a backup of the current map.
   */
  async createBackup(): Promise<boolean> {
    const map = this.currentMap;
    if (!map || !this.worldName) {
      return false;
    }

    // Save current state first
    await this.manualSave();

    // Then create backup
    return await this.mapStorage.backupMap(this.worldName, map.name);
  }

  /**
   * Load a map from filesystem (fallback if WebSocket/API fails).
   */
  async loadFromFilesystem(worldName: string, mapName: string): Promise<LobbyMap | null> {
    return await this.mapStorage.loadMap(worldName, mapName);
  }
}
